{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "The closest analogue, (+)-bicuculline, was directly shown to penetrate rat brain in a dose-dependent manner by LC-MS/MS, indicating that the phthalideisoquinoline scaffold supports BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Schisandrin B, a related polycyclic alkaloid/lignan, had a measured logPSFu,brain of -3.2 and was classified as BBB-permeable, providing quantitative support for meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nuciferine reached brain concentrations almost equal to plasma in rats, demonstrating effective BBB crossing for this alkaloid class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Corydaline was detected in rat CSF and showed brain levels close to other tissues after oral dosing, supporting CNS access for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Hernandezine achieved a brain Cmax nearly equal to plasma Cmax after IV dosing, further confirming that these polycyclic alkaloids can access the brain.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple structurally related phthalideisoquinoline and polycyclic alkaloids with direct brain, CSF, or brain/plasma measurements demonstrate BBB permeability. The closest analogue, bicuculline, is directly brain-penetrant, and the query itself is a known CNS-active antitussive alkaloid. No evidence contradicts meaningful CNS access.",
  "evidence_gaps": [
    "No direct noscapine-specific brain or CSF measurement is present in the provided records.",
    "Quantitative unbound brain-to-plasma ratio and efflux-transporter data for the query are not directly reported.",
    "Most evidence comes from related alkaloids rather than noscapine itself, though the structural and pharmacological analogy is strong."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

